import { useState, useEffect, useMemo, useCallback, useRef } from "react";
import { useSearchParams } from "react-router-dom";
import { Search, AlertTriangle, Store, MapPin, RefreshCw, Package, ChevronDown, ChevronUp, Grid3X3, List } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import Header from "@/components/landing/Header";
import Footer from "@/components/landing/Footer";
import BackToTop from "@/components/landing/BackToTop";
import { Skeleton } from "@/components/ui/skeleton";
import { Reveal } from "@/components/landing/motion";
import { fetchAllChestShops, fetchChestShops, fetchWarpZones } from "@/lib/castiaClient";
import { fmt } from "@/lib/parseItem";
import { openShopDetail } from "@/components/landing/DetailDrawer";
import Breadcrumb from "@/components/ui/Breadcrumb";
import { distinctShopRows, stockLabel, stockTimestamp } from "@/lib/shopStock";
import { rankShopSuggestions, shopRowSearchScore } from "@/lib/shopSearch";
import { decorateShopArea, shopAreaOptions } from "@/lib/shopAreas";

function skeletonRows(count = 8) {
  return Array.from({ length: count }).map((_, i) => (
    <div key={i} className="border-b border-white/5 last:border-0 px-4 py-3 flex items-center gap-4">
      <Skeleton className="h-4 w-32" />
      <Skeleton className="h-4 w-24" />
      <Skeleton className="h-4 w-16 ml-auto" />
      <Skeleton className="h-4 w-20 ml-auto" />
      <Skeleton className="h-4 w-36 hidden md:block" />
      <Skeleton className="h-4 w-16 hidden md:block" />
    </div>
  ));
}

export default function ShopsPage() {
  const [rows, setRows] = useState([]);
  const [zones, setZones] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadingMore, setLoadingMore] = useState(false);
  const [nextCursor, setNextCursor] = useState(null);
  const [error, setError] = useState(null);
  const [searchParams, setSearchParams] = useSearchParams();
  const sellerFilter = searchParams.get("seller") || "";
  const [q, setQ] = useState(() => searchParams.get("q") || searchParams.get("item") || "");
  const [deferredQuery, setDeferredQuery] = useState(q);
  useEffect(() => {
    const timer = setTimeout(() => setDeferredQuery(q), 250);
    return () => clearTimeout(timer);
  }, [q]);
  useEffect(() => {
    setQ(searchParams.get("q") || searchParams.get("item") || "");
  }, [searchParams]);
  useEffect(() => {
    if (!searchParams.has("item")) return;
    const next = new URLSearchParams(searchParams);
    next.set("q", next.get("item"));
    next.delete("item");
    setSearchParams(next, { replace: true });
  }, [searchParams, setSearchParams]);
  const inputRef = useRef(null);
  const filterRef = useRef(null);
  const requestEpochRef = useRef(0);
  const requestControllerRef = useRef(null);
  const appendInFlightRef = useRef(false);
  const [warpFilter, setWarpFilter] = useState("");
  const [sortKey, setSortKey] = useState("updated_at");
  const [sortDir, setSortDir] = useState("desc");
  const [viewMode, setViewMode] = useState("table");
  const [suggestionsOpen, setSuggestionsOpen] = useState(false);
  const [activeSuggestion, setActiveSuggestion] = useState(-1);

  useEffect(() => {
    if (inputRef.current) inputRef.current.focus();
  }, []);

  const doFetch = useCallback(async ({ append = false, cursor = null } = {}) => {
    // A refresh is authoritative: invalidate any pagination response that was
    // started for the old result set. This also avoids two rapid "load more"
    // clicks adding the same cursor page twice before React repaints.
    if (append && (appendInFlightRef.current || !cursor)) return;
    if (!append) {
      requestEpochRef.current += 1;
      requestControllerRef.current?.abort();
      requestControllerRef.current = new AbortController();
      appendInFlightRef.current = false;
      setNextCursor(null);
    } else {
      appendInFlightRef.current = true;
    }
    const epoch = requestEpochRef.current;
    const controller = requestControllerRef.current;
    if (append) setLoadingMore(true);
    else setLoading(true);
    setError(null);
    try {
      const [initialShopData, zoneData] = await Promise.all([
        (["price", "stock"].includes(sortKey) || warpFilter ? fetchAllChestShops : fetchChestShops)({
          item: deferredQuery.trim() || undefined,
          seller: sellerFilter || undefined,
          limit: 100,
          sort: sortKey ? `${sortKey}.${sortDir}` : undefined,
          cursor: append ? cursor : undefined,
          signal: controller?.signal,
          force: !append,
        }),
        append ? Promise.resolve(null) : fetchWarpZones({ limit: 500, signal: controller?.signal, force: true })
          .catch(() => ({ zones: [] })),
      ]);
      if (epoch !== requestEpochRef.current || controller?.signal.aborted) return;

      // The deployed Worker is upgraded independently of GitHub Pages. Keep
      // partial/typo search useful during that rollout if an older API still
      // returns zero rows for a non-exact item query.
      let shopData = initialShopData;
      const initialRows = Array.isArray(shopData) ? shopData : shopData?.shops || shopData?.rows || [];
      if (!append && deferredQuery.trim() && initialRows.length === 0) {
        shopData = await fetchAllChestShops({
          sort: sortKey ? `${sortKey}.${sortDir}` : undefined,
          signal: controller?.signal,
        });
        if (epoch !== requestEpochRef.current || controller?.signal.aborted) return;
      }
      
      const newShops = Array.isArray(shopData) ? shopData : shopData?.shops || shopData?.rows || [];
      setRows(prev => distinctShopRows(append ? [...prev, ...newShops] : newShops));
      setNextCursor(shopData?.nextCursor || null);
      
      if (zoneData) {
        setZones(Array.isArray(zoneData) ? zoneData : zoneData?.zones || []);
      }
    } catch (e) {
      if (epoch === requestEpochRef.current && e?.name !== "AbortError") {
        setError(e.message || "Failed to load chest shops");
      }
    } finally {
      if (epoch === requestEpochRef.current) {
        setLoading(false);
        setLoadingMore(false);
      }
      if (append) appendInFlightRef.current = false;
    }
  }, [deferredQuery, sortKey, sortDir, warpFilter, sellerFilter]);

  useEffect(() => {
    doFetch();
  }, [doFetch]);

  const query = deferredQuery.trim();
  const rowsWithWarps = useMemo(() => {
    return rows.map((r) => decorateShopArea(r, zones));
  }, [rows, zones]);

  const zoneNames = useMemo(() => {
    return shopAreaOptions(zones, rowsWithWarps);
  }, [rowsWithWarps, zones]);

  const filtered = useMemo(() => {
    let f = [...rowsWithWarps];
    if (query) {
      f = f.filter((r) => {
        return shopRowSearchScore(query, r) > 0;
      });
    }
    
    // External filter from searchParams (e.g. from "Where to Buy" redirects)
    const paramSeller = searchParams.get("seller")?.toLowerCase();
    if (paramSeller) {
      f = f.filter(r => (r.seller || "").toLowerCase() === paramSeller);
    }

    if (warpFilter) {
      f = f.filter((r) => r.shopGroupKey === warpFilter);
    }
    if (sortKey === "price") {
      f.sort((a, b) => sortDir === "asc" ? a.unitPrice - b.unitPrice : b.unitPrice - a.unitPrice);
    } else if (sortKey === "stock") {
      f.sort((a, b) => {
        if (a.stockCount == null) return b.stockCount == null ? 0 : 1;
        if (b.stockCount == null) return -1;
        return sortDir === "asc" ? a.stockCount - b.stockCount : b.stockCount - a.stockCount;
      });
    } else if (sortKey === "freshness") {
      f.sort((a, b) => {
        const ta = a.lastSeenAt ? new Date(a.lastSeenAt).getTime() : 0;
        const tb = b.lastSeenAt ? new Date(b.lastSeenAt).getTime() : 0;
        return sortDir === "asc" ? ta - tb : tb - ta;
      });
    }
    return f;
  }, [rowsWithWarps, query, warpFilter, sortKey, sortDir, searchParams]);

  const changeQuery = (value) => {
    setQ(value);
    const next = new URLSearchParams(searchParams);
    next.delete("item");
    if (value) next.set("q", value); else next.delete("q");
    setSearchParams(next, { replace: true });
  };

  const resetFilters = () => {
    setQ("");
    const next = new URLSearchParams(searchParams);
    next.delete("item"); next.delete("q"); next.delete("seller");
    setSearchParams(next, { replace: true });
    setWarpFilter("");
    setSortKey("updated_at");
    setSortDir("desc");
    inputRef.current?.focus();
  };

  const deduped = useMemo(() => distinctShopRows(filtered), [filtered]);

  const visible = deduped;
  const suggestions = useMemo(() => rankShopSuggestions(rowsWithWarps, q), [rowsWithWarps, q]);

  const selectSuggestion = (name) => {
    changeQuery(name);
    setSuggestionsOpen(false);
    setActiveSuggestion(-1);
    inputRef.current?.focus();
  };

  const locStr = (r) => {
    const parts = [];
    if (r.dimensionKey) parts.push(r.dimensionKey.replace(/_/g, " "));
    if (r.x != null && r.y != null && r.z != null) parts.push(`(${r.x}, ${r.y}, ${r.z})`);
    return parts.join(" ") || "\u2014";
  };

  return (
    <div data-testid="shops-page" className="min-h-screen bg-bg-base text-white font-body">
      <Header />
      <main className="pt-32 pb-24">
        <div className="max-w-7xl mx-auto px-6 md:px-12 lg:px-16">
          <Reveal>
            <Breadcrumb
              items={[
                { label: "Home", href: "/" },
                { label: "Shops" },
              ]}
              icon={Store}
              color="text-indigo-400"
            />
            <h1 className="font-heading text-5xl sm:text-6xl lg:text-7xl tracking-tighter font-black leading-[0.95]">
              Chest <span className="text-indigo-400">Shops</span>
            </h1>
            <p className="mt-6 text-zinc-400 max-w-2xl text-lg">
              Browse chest-shop listings across the server. Each entry shows the seller, stock, price, and physical location.
            </p>
          </Reveal>

          {/* Search + controls — sticky */}
          <div className="sticky top-24 z-10 bg-bg-base/80 backdrop-blur-md -mx-6 md:-mx-12 lg:-mx-16 px-6 md:px-12 lg:px-16 py-4 border-b border-white/5 mt-10">
            <div className="flex items-center gap-3 flex-wrap">
              <div className="relative flex-1 min-w-[140px] sm:min-w-[200px] max-w-sm">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-zinc-500 pointer-events-none" />
                <input
                  ref={inputRef}
                  data-testid="shops-search"
                  aria-label="Search shops by item or seller name"
                  value={q}
                  onChange={(e) => { changeQuery(e.target.value); setSuggestionsOpen(true); setActiveSuggestion(-1); }}
                  onFocus={() => setSuggestionsOpen(true)}
                  onBlur={() => window.setTimeout(() => setSuggestionsOpen(false), 120)}
                  onKeyDown={(e) => {
                    if (!suggestions.length) return;
                    if (e.key === "ArrowDown") { e.preventDefault(); setSuggestionsOpen(true); setActiveSuggestion((index) => (index + 1) % suggestions.length); }
                    else if (e.key === "ArrowUp") { e.preventDefault(); setActiveSuggestion((index) => (index - 1 + suggestions.length) % suggestions.length); }
                    else if (e.key === "Enter" && activeSuggestion >= 0) { e.preventDefault(); selectSuggestion(suggestions[activeSuggestion]); }
                    else if (e.key === "Escape") { setSuggestionsOpen(false); setActiveSuggestion(-1); }
                  }}
                  placeholder="Search items or sellers…"
                  autoComplete="off"
                  className="w-full bg-white/[0.04] border border-white/10 rounded-sm pl-10 pr-4 py-2.5 text-sm text-white placeholder:text-zinc-600 focus:outline-none focus:border-indigo-500/50 transition-colors"
                />
                {suggestionsOpen && suggestions.length > 0 && (
                  <div role="listbox" aria-label="Item suggestions" className="absolute z-30 top-[calc(100%+0.35rem)] inset-x-0 overflow-hidden rounded-sm border border-white/10 bg-[#16191f] shadow-2xl">
                    {suggestions.map((name, index) => (
                      <button
                        key={name}
                        type="button"
                        role="option"
                        aria-selected={activeSuggestion === index}
                        onMouseDown={(e) => e.preventDefault()}
                        onClick={() => selectSuggestion(name)}
                        className={`block w-full px-4 py-2.5 text-left text-sm transition-colors ${activeSuggestion === index ? "bg-indigo-500/20 text-white" : "text-zinc-300 hover:bg-white/[0.06] hover:text-white"}`}
                      >
                        {name}
                      </button>
                    ))}
                  </div>
                )}
                {q && (
                    <button
                      onClick={resetFilters}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-zinc-500 hover:text-white"
                      aria-label="Clear search"
                    >
                    <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M18 6L6 18M6 6l12 12"/></svg>
                  </button>
                )}
              </div>
              <button
                onClick={() => doFetch()}
                data-testid="shops-refresh"
                className="inline-flex items-center gap-2 border border-white/10 hover:border-white/30 text-zinc-300 hover:text-white font-bold uppercase tracking-[0.18em] text-[10px] px-4 py-2.5 rounded-sm transition-colors"
              >
                <RefreshCw className="w-3.5 h-3.5" /> Refresh
              </button>
              <select
                aria-label="Sort listings"
                value={`${sortKey}.${sortDir}`}
                onChange={(e) => {
                  const [k, d] = e.target.value.split(".");
                  setSortKey(k);
                  setSortDir(d);
                }}
                className="bg-white/[0.04] border border-white/10 rounded-sm px-4 py-2.5 text-xs text-zinc-300 font-bold uppercase tracking-[0.18em] focus:outline-none focus:border-indigo-500/50 cursor-pointer"
              >
                <option value="updated_at.desc">Latest Updated</option>
                <option value="price.asc">Unit price: Low to High</option>
                <option value="price.desc">Unit price: High to Low</option>
                <option value="stock.desc">Stock: High to Low</option>
                <option value="stock.asc">Stock: Low to High</option>
                <option value="last_seen_at.desc">Recently Seen</option>
              </select>

              <select
                ref={filterRef}
                aria-label="Filter by shop area or independent warp"
                value={warpFilter}
                onChange={(e) => setWarpFilter(e.target.value)}
                className="bg-white/[0.04] border border-white/10 rounded-sm px-4 py-2.5 text-xs text-zinc-300 font-bold uppercase tracking-[0.18em] focus:outline-none focus:border-indigo-500/50 cursor-pointer"
              >
                <option value="">All Areas / Warps</option>
                {zoneNames.map(({value, label}) => (
                  <option key={value} value={value} className="bg-bg-deep">{label}</option>
                ))}
              </select>
              <div className="flex border border-white/10 rounded-sm overflow-hidden ml-auto">
                <button
                  onClick={() => setViewMode("table")}
                  className={`p-2 transition-colors ${viewMode === "table" ? "bg-indigo-500/20 text-indigo-400" : "text-zinc-500 hover:text-white"}`}
                  aria-label="Table view"
                >
                  <List className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setViewMode("card")}
                  className={`p-2 transition-colors ${viewMode === "card" ? "bg-indigo-500/20 text-indigo-400" : "text-zinc-500 hover:text-white"}`}
                  aria-label="Card view"
                >
                  <Grid3X3 className="w-4 h-4" />
                </button>
              </div>
            </div>
          </div>

          {/* Loading state */}
          {loading && (
            <div className="mt-6 border border-white/10 rounded-2xl overflow-hidden">
              {skeletonRows(8)}
            </div>
          )}

          {/* Error state */}
          {!loading && error && (
            <Reveal>
              <div data-testid="shops-error" className="mt-16 text-center max-w-md mx-auto">
                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-red-500/10 border border-red-500/30 mb-6">
                  <AlertTriangle className="w-7 h-7 text-red-400" />
                </div>
                <h2 className="font-heading text-2xl font-black mb-3">Failed to load shops</h2>
                <p className="text-zinc-400 text-sm leading-relaxed mb-6">{error}</p>
                <button
                  onClick={() => doFetch()}
                  className="inline-flex items-center gap-2 bg-indigo-500 hover:bg-indigo-400 text-black font-bold uppercase tracking-[0.18em] text-xs px-5 py-3 rounded-sm transition-colors"
                >
                  <RefreshCw className="w-4 h-4" /> Retry
                </button>
              </div>
            </Reveal>
          )}

          {/* Empty state */}
          {!loading && !error && filtered.length === 0 && (
            <Reveal>
              <div data-testid="shops-empty" className="mt-16 text-center max-w-md mx-auto">
                <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-indigo-500/10 border border-indigo-500/30 mb-6">
                  <Store className="w-7 h-7 text-indigo-400" />
                </div>
                <h2 className="font-heading text-2xl font-black mb-3">No shops found</h2>
                <p className="text-zinc-400 text-sm leading-relaxed mb-6">
                  {query ? "Try a different search term or clear the filter." : "No chest shops are currently available."}
                </p>
                <button
                  onClick={resetFilters}
                  className="inline-flex items-center gap-2 bg-indigo-500 hover:bg-indigo-400 text-black font-bold uppercase tracking-[0.18em] text-xs px-5 py-3 rounded-sm transition-colors"
                >
                  Clear filters
                </button>
              </div>
            </Reveal>
          )}

          {/* Results */}
          {!loading && !error && visible.length > 0 && (
            <Reveal delay={0.1} className="mt-6">
              <div className="text-xs text-zinc-500 mb-3 font-mono">{deduped.length} shop{deduped.length === 1 ? "" : "s"}{query ? ` matching "${q}"` : ""}{filtered.length > deduped.length ? <span className="text-zinc-600 ml-1">({filtered.length} total chests)</span> : ""}</div>

              <AnimatePresence mode="wait">
                {viewMode === "table" ? (
                  <motion.div
                    key="table"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="border border-white/10 rounded-2xl overflow-hidden"
                  >
                    <div className="overflow-x-auto no-scrollbar custom-scrollbar">
                      <table className="w-full text-sm">
                        <thead>
                          <tr className="bg-white/[0.02] border-b border-white/10 text-left">
                            <th className="px-4 py-3 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-500">Item</th>
                            <th className="px-4 py-3 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-500">Seller</th>
                            <th className="px-4 py-3 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-500 text-right">
                              <button
                                onClick={() => { setSortKey(sortKey === "stock" && sortDir === "asc" ? "" : "stock"); setSortDir("asc"); }}
                                className="inline-flex items-center gap-1 hover:text-white transition-colors"
                              >
                                Stock
                                {sortKey === "stock" ? (sortDir === "asc" ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />) : null}
                              </button>
                            </th>
                            <th className="px-4 py-3 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-500 text-right">
                              <button
                                onClick={() => { if (sortKey === "price" && sortDir === "asc") { setSortKey(""); } else { setSortKey("price"); setSortDir("asc"); } }}
                                className="inline-flex items-center gap-1 hover:text-white transition-colors"
                              >
                                Price
                                {sortKey === "price" ? (sortDir === "asc" ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />) : null}
                              </button>
                            </th>
                            <th className="px-4 py-3 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-500 hidden md:table-cell">Location</th>
                            <th className="px-4 py-3 font-mono text-[10px] uppercase tracking-[0.2em] text-zinc-500 hidden md:table-cell">Warp</th>
                          </tr>
                        </thead>
                        <tbody>
                          {visible.map((r, i) => (
                            <motion.tr
                              key={JSON.stringify([r.serverKey, r.dimensionKey, r.x, r.y, r.z])}
                              initial={{ opacity: 0 }}
                              animate={{ opacity: 1 }}
                              transition={{ delay: i * 0.008 }}
                              onClick={() => openShopDetail(searchParams, setSearchParams, r)}
                              role="button"
                              tabIndex={0}
                              onKeyDown={(e) => { if (e.key === "Enter") openShopDetail(searchParams, setSearchParams, r); }}
                              className="border-b border-white/5 last:border-0 hover:bg-white/[0.03] transition-colors cursor-pointer"
                            >
                              <td className="px-4 py-3">
                                <span className="font-heading font-bold text-white">{r.itemName || r.itemTag || "\u2014"}</span>
                                {r.count > 1 && <span className="ml-2 font-mono text-[9px] text-indigo-400 bg-indigo-500/10 border border-indigo-500/30 rounded-full px-1.5 py-0.5">{r.count}x</span>}
                              </td>
                              <td className="px-4 py-3">
                                <span className="text-zinc-300">{r.seller || "\u2014"}</span>
                              </td>
                              <td className="px-4 py-3 text-right">
                                <span className="tabular inline-flex items-center gap-1 justify-end">
                                  <Package className="w-3 h-3 text-zinc-500 shrink-0" />
                                  <span title={stockTimestamp(r)}>{stockLabel(r)}</span>
                                </span>
                              </td>
                              <td className="px-4 py-3 text-right">
                                <span className="font-mono tabular text-indigo-400 font-bold">{r.unitPrice > 0 ? fmt(r.unitPrice) : "\u2014"}</span>
                              </td>
                              <td className="px-4 py-3 hidden md:table-cell">
                                <span className="inline-flex items-center gap-1 text-zinc-400">
                                  <MapPin className="w-3 h-3 text-zinc-500 shrink-0" />
                                  {locStr(r)}
                                </span>
                              </td>
                              <td className="px-4 py-3 hidden md:table-cell">
                                <span className="text-zinc-400" title={r.warpInferred ? 'Suggested warp based on distance and height' : undefined}>{r.shopAreaName ? `${r.shopAreaName} · /pw ${r.warpName}` : r.warpName || "\u2014"}{r.warpInferred && <span className="ml-1 text-[10px] text-zinc-500">≈</span>}</span>
                              </td>
                            </motion.tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  </motion.div>
                ) : (
                  <motion.div
                    key="card"
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    exit={{ opacity: 0 }}
                    className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4"
                  >
                    {visible.map((r, i) => (
                      <motion.div
                        key={JSON.stringify([r.serverKey, r.dimensionKey, r.x, r.y, r.z])}
                        initial={{ opacity: 0, y: 12 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: i * 0.015 }}
                        onClick={() => openShopDetail(searchParams, setSearchParams, r)}
                        role="button"
                        tabIndex={0}
                        onKeyDown={(e) => { if (e.key === "Enter") openShopDetail(searchParams, setSearchParams, r); }}
                        className="bg-white/[0.02] border border-white/10 rounded-xl p-4 hover:bg-white/[0.04] hover:-translate-y-0.5 transition-all cursor-pointer"
                      >
                        <div className="font-heading font-bold text-white text-sm truncate">
                          {r.itemName || r.itemTag || "\u2014"}
                          {r.count > 1 && <span className="ml-2 font-mono text-[9px] text-indigo-400 bg-indigo-500/10 border border-indigo-500/30 rounded-full px-1.5 py-0.5">{r.count}x</span>}
                        </div>
                        <div className="text-xs text-zinc-400 mt-1">{r.seller || "\u2014"}</div>
                        <div className="flex items-center justify-between mt-3">
                          <span className="font-mono tabular text-indigo-400 font-bold text-sm">{r.unitPrice > 0 ? fmt(r.unitPrice) : "\u2014"}</span>
                          <span title={stockTimestamp(r)} className="text-[10px] text-zinc-500 tabular">{stockLabel(r)}</span>
                        </div>
                        <div className="flex items-center gap-2 mt-2 text-[10px] text-zinc-500">
                          <MapPin className="w-3 h-3 shrink-0" />
                          <span className="truncate" title={r.warpInferred ? 'Suggested warp based on distance and height' : undefined}>{r.shopAreaName ? `${r.shopAreaName} · /pw ${r.warpName}` : r.warpName || locStr(r)}{r.warpInferred ? ' ≈' : ''}</span>
                        </div>
                      </motion.div>
                    ))}
                  </motion.div>
                )}
              </AnimatePresence>

              {/* Load More / Pagination */}
              {nextCursor && (
                <div className="flex justify-center mt-12">
                  <button
                    disabled={loadingMore}
                    onClick={() => doFetch({ append: true, cursor: nextCursor })}
                    className="inline-flex items-center gap-2 bg-white/[0.04] border border-white/10 hover:border-white/30 text-zinc-300 hover:text-white font-bold uppercase tracking-[0.2em] text-xs px-8 py-4 rounded-sm transition-all active:scale-95 disabled:opacity-50 disabled:pointer-events-none"
                  >
                    {loadingMore ? (
                      <>
                        <RefreshCw className="w-4 h-4 animate-spin" /> Loading...
                      </>
                    ) : (
                      "Load More Listings"
                    )}
                  </button>
                </div>
              )}
            </Reveal>
          )}
        </div>
      </main>
      <Footer />
      <BackToTop />
    </div>
  );
}
